  for(let i=0;i<5;i++)p.sole.push(new THREE.BoxGeometry(.134,.011,.013).translate(side*.158,.044,-.885+i*.048));
  p.shirt.push(limb([[side*.199,.965,-.275],[side*.249,.86,-.31],[side*.274,.716,-.34],[side*.247,.64,-.45],[side*.201,.625,-.54]],[[.087,.081],[.085,.075],[.078,.063],[.067,.056],[.046,.045]],20,.042));
