 for(const side of[-1,1]){p.skin.push(ball([side*.080,1.219,-.228],[.015,.029,.018]));p.shadow.push(ball([side*.088,1.22,-.24],[.005,.015,.006],10,6));p.shadow.push(tube([[side*.013,1.252,-.319],[side*.035,1.257,-.32],[side*.054,1.251,-.310]],.0022,12,4));p.shadow.push(tube([[side*.018,1.237,-.321],[side*.032,1.239,-.321],[side*.048,1.238,-.315]],.0015,10,4));}
 p.lips.push(tube([[-.024,1.154,-.323],[-.010,1.154,-.33],[0,1.153,-.332],[.012,1.154,-.33],[.024,1.155,-.323]],.0015,16,4));
 p.cap.push(bodyLoft([[0,1.283,-.235,.083,.079],[0,1.316,-.23,.083,.08],[0,1.345,-.227,.067,.066],[0,1.369,-.223,.039,.035],[0,1.374,-.223,.009,.009]],28));
 p.cap.push(ball([0,1.287,-.314],[.091,.009,.10],24,8));p.seam.push(tube([[-.074,1.30,-.254],[0,1.374,-.23],[.074,1.30,-.254]],.0012,20,4));p.seam.push(tube([[0,1.291,-.412],[-.053,1.29,-.387],[-.077,1.288,-.34]],.0012,20,4));
